-- one_classics_nexus_test.appraisal_requests definition

CREATE TABLE `appraisal_requests` (
  `appraisal_request_id` char(36) NOT NULL,
  `request_number` varchar(30) NOT NULL,
  `status_code` varchar(30) NOT NULL DEFAULT 'DRAFT',
  `disposition_reason` varchar(1000) DEFAULT NULL,
  `client_id` char(36) DEFAULT NULL,
  `primary_client_contact_id` char(36) DEFAULT NULL,
  `intended_use_id` char(36) DEFAULT NULL,
  `intended_use_custom_narrative` text DEFAULT NULL,
  `requested_effective_date_utc` datetime(6) DEFAULT NULL,
  `requested_effective_date_precision` varchar(20) DEFAULT NULL,
  `requested_effective_date_time_zone` varchar(64) DEFAULT NULL,
  `requested_value_definition_id` char(36) DEFAULT NULL,
  `requested_scope_summary` text DEFAULT NULL,
  `converted_appraisal_id` char(36) DEFAULT NULL,
  `client_snapshot_json` longtext DEFAULT NULL,
  `client_contact_snapshot_json` longtext DEFAULT NULL,
  `intended_use_name_snapshot` varchar(200) DEFAULT NULL,
  `intended_use_description_snapshot` text DEFAULT NULL,
  `intended_use_category_snapshot` varchar(100) DEFAULT NULL,
  `party_identification_reviewed_at_utc` datetime(6) DEFAULT NULL,
  `party_identification_reviewed_by_user_id` char(36) DEFAULT NULL,
  `submitted_at_utc` datetime(6) DEFAULT NULL,
  `submitted_by_user_id` char(36) DEFAULT NULL,
  `accepted_at_utc` datetime(6) DEFAULT NULL,
  `accepted_by_user_id` char(36) DEFAULT NULL,
  `converted_at_utc` datetime(6) DEFAULT NULL,
  `converted_by_user_id` char(36) DEFAULT NULL,
  `closed_at_utc` datetime(6) DEFAULT NULL,
  `closed_by_user_id` char(36) DEFAULT NULL,
  `row_version` bigint(20) unsigned NOT NULL DEFAULT 1,
  `created_at_utc` datetime(6) NOT NULL DEFAULT utc_timestamp(6),
  `created_by_user_id` char(36) NOT NULL,
  `updated_at_utc` datetime(6) NOT NULL DEFAULT utc_timestamp(6),
  `updated_by_user_id` char(36) NOT NULL,
  PRIMARY KEY (`appraisal_request_id`),
  UNIQUE KEY `uq_appraisal_requests_number` (`request_number`),
  UNIQUE KEY `uq_appraisal_requests_request_number` (`request_number`),
  UNIQUE KEY `uq_appraisal_requests_converted_appraisal` (`converted_appraisal_id`),
  KEY `idx_appraisal_requests_client` (`client_id`,`created_at_utc`),
  KEY `idx_appraisal_requests_client_status` (`client_id`,`status_code`,`updated_at_utc`),
  KEY `idx_appraisal_requests_primary_contact` (`primary_client_contact_id`,`status_code`),
  KEY `idx_appraisal_requests_intended_use` (`intended_use_id`,`status_code`),
  KEY `idx_appraisal_requests_value_definition` (`requested_value_definition_id`),
  KEY `idx_appraisal_requests_status_updated` (`status_code`,`updated_at_utc`),
  KEY `idx_appraisal_requests_review_queue` (`status_code`,`party_identification_reviewed_at_utc`,`created_at_utc`),
  KEY `idx_appraisal_requests_requested_effective_date` (`requested_effective_date_utc`),
  CONSTRAINT `fk_appraisal_requests_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`client_id`),
  CONSTRAINT `fk_appraisal_requests_converted_appraisal` FOREIGN KEY (`converted_appraisal_id`) REFERENCES `appraisals` (`appraisal_id`),
  CONSTRAINT `fk_appraisal_requests_intended_use` FOREIGN KEY (`intended_use_id`) REFERENCES `intended_uses` (`intended_use_id`),
  CONSTRAINT `fk_appraisal_requests_value_definition` FOREIGN KEY (`requested_value_definition_id`) REFERENCES `requested_value_definitions` (`requested_value_definition_id`),
  CONSTRAINT `fk_appraisal_requests_primary_contact` FOREIGN KEY (`primary_client_contact_id`) REFERENCES `client_contacts` (`client_contact_id`),
  CONSTRAINT `ck_appraisal_requests_id_uuid` CHECK (cast(`appraisal_request_id` as char charset binary) = cast(lcase(`appraisal_request_id`) as char charset binary) and cast(`appraisal_request_id` as char charset binary) regexp '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  CONSTRAINT `ck_appraisal_requests_number_required` CHECK (char_length(trim(`request_number`)) > 0),
  CONSTRAINT `ck_appraisal_requests_status` CHECK (`status_code` in ('DRAFT','SUBMITTED','UNDER_REVIEW','ACCEPTED','CONVERTED','DECLINED','CANCELLED','WITHDRAWN')),
  CONSTRAINT `ck_appraisal_requests_client_uuid` CHECK (`client_id` is null or cast(`client_id` as char charset binary) = cast(lcase(`client_id`) as char charset binary) and cast(`client_id` as char charset binary) regexp '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  CONSTRAINT `ck_appraisal_requests_contact_uuid` CHECK (`primary_client_contact_id` is null or cast(`primary_client_contact_id` as char charset binary) = cast(lcase(`primary_client_contact_id`) as char charset binary) and cast(`primary_client_contact_id` as char charset binary) regexp '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  CONSTRAINT `ck_appraisal_requests_intended_use_uuid` CHECK (`intended_use_id` is null or cast(`intended_use_id` as char charset binary) = cast(lcase(`intended_use_id`) as char charset binary) and cast(`intended_use_id` as char charset binary) regexp '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
  CONSTRAINT `ck_appraisal_requests_date_precision` CHECK (`requested_effective_date_precision` is null or `requested_effective_date_precision` in ('DATE_ONLY','DATE_TIME')),
  CONSTRAINT `ck_appraisal_requests_requested_date` CHECK (`requested_effective_date_utc` is null and `requested_effective_date_precision` is null and `requested_effective_date_time_zone` is null or `requested_effective_date_utc` is not null and `requested_effective_date_precision` is not null),
  CONSTRAINT `ck_appraisal_requests_client_snapshot_json` CHECK (`client_snapshot_json` is null or json_valid(`client_snapshot_json`)),
  CONSTRAINT `ck_appraisal_requests_contact_snapshot_json` CHECK (`client_contact_snapshot_json` is null or json_valid(`client_contact_snapshot_json`)),
  CONSTRAINT `ck_appraisal_requests_party_review_pair` CHECK (`party_identification_reviewed_at_utc` is null and `party_identification_reviewed_by_user_id` is null or `party_identification_reviewed_at_utc` is not null and `party_identification_reviewed_by_user_id` is not null),
  CONSTRAINT `ck_appraisal_requests_conversion_pair` CHECK (`converted_appraisal_id` is null and `converted_at_utc` is null and `converted_by_user_id` is null or `converted_appraisal_id` is not null and `converted_at_utc` is not null and `converted_by_user_id` is not null),
  CONSTRAINT `ck_appraisal_requests_converted_status` CHECK (`status_code` = 'CONVERTED' and `converted_appraisal_id` is not null or `status_code` <> 'CONVERTED' and `converted_appraisal_id` is null),
  CONSTRAINT `ck_appraisal_requests_client_gate` CHECK (`status_code` = 'DRAFT' or `client_id` is not null),
  CONSTRAINT `ck_appraisal_requests_intended_use_gate` CHECK (`status_code` not in ('ACCEPTED','CONVERTED') or `intended_use_id` is not null),
  CONSTRAINT `ck_appraisal_requests_acceptance_audit` CHECK (`status_code` not in ('ACCEPTED','CONVERTED') or `accepted_at_utc` is not null and `accepted_by_user_id` is not null),
  CONSTRAINT `ck_appraisal_requests_closed_status` CHECK (`status_code` not in ('DECLINED','CANCELLED','WITHDRAWN') or nullif(trim(`disposition_reason`),'') is not null and `closed_at_utc` is not null and `closed_by_user_id` is not null),
  CONSTRAINT `ck_appraisal_requests_row_version` CHECK (`row_version` >= 1),
  CONSTRAINT `ck_appraisal_requests_audit_dates` CHECK (`updated_at_utc` >= `created_at_utc`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Pre-appraisal intake requests and proposed client/use identification';